1	//! `MessageTranslator` — Anthropic SSE events → `ModelEvent` stream.
2	
3	use std::collections::HashMap;
4	
5	use paigasus_helikon_core::{FinishReason, ModelError, ModelEvent};
6	
7	use crate::error::map_error_type;
8	use crate::provider_data::{AnthropicData, ThinkingBlock};
9	use crate::sse::{
10	    AnthropicEvent, ContentBlockDelta, ContentBlockHead, MessageDeltaUsage, MessageStartUsage,
11	};
12	use crate::translate::response_format::SYNTHESIZED_TOOL_NAME;
13	
14	#[derive(Debug)]
15	enum BlockState {
16	    Text,
17	    Thinking {
18	        text: String,
19	        signature: String,
20	    },
21	    RedactedThinking {
22	        data: String,
23	    },
24	    ToolUse {
25	        call_id: String,
26	        name: String,
27	        name_emitted: bool,
28	    },
29	}
30	
31	/// State machine for one streaming response.
32	///
33	/// `synthesizing_output: true` means a `ResponseFormat::JsonSchema`/`JsonObject`
34	/// request was sent. When the synthesized tool's content block starts, its
35	/// `input_json_delta` events are remapped to `TokenDelta`s and the
36	/// `stop_reason: "tool_use"` is rewritten to `Stop` if it was the only tool fired.
37	pub(crate) struct MessageTranslator {
38	    blocks: HashMap<u32, BlockState>,
39	    last_input_tokens: u32,
40	    last_cached_input_tokens: Option<u32>,
41	    stop_reason: Option<String>,
42	    synthesizing_output: bool,
43	    synthesized_tool_index: Option<u32>,
44	    other_tool_fired: bool,
45	    terminal_emitted: bool,
46	    /// The first text block of the response has stopped.
47	    text_position_recorded: bool,
48	    /// The stream has emitted a `block` part of this response.
49	    block_emitted: bool,
50	    /// Position records that wait for the first `block` part.
51	    waiting_positions: Vec<ModelEvent>,
52	}
53	
54	impl MessageTranslator {
55	    pub(crate) fn new(synthesizing_output: bool) -> Self {
56	        Self {
57	            blocks: HashMap::new(),
58	            last_input_tokens: 0,
59	            last_cached_input_tokens: None,
60	            stop_reason: None,
61	            synthesizing_output,
62	            synthesized_tool_index: None,
63	            other_tool_fired: false,
64	            terminal_emitted: false,
65	            text_position_recorded: false,
66	            block_emitted: false,
67	            waiting_positions: Vec::new(),
68	        }
69	    }
70	
71	    /// Consume one event. Returns the emitted ModelEvents (most calls
72	    /// emit zero or one; `message_delta` carrying both stop_reason and
73	    /// usage emits one Usage followed by Finish on `message_stop`). A
74	    /// terminal event (`Finish` or an `Err`) is emitted at most once per
75	    /// stream, and a later `message_delta`'s `Usage` is suppressed once one
76	    /// has been emitted. Content deltas are deliberately *not* guarded: a
77	    /// malformed stream that keeps sending `content_block_delta` after
78	    /// `message_stop` would still yield them. A clean end-of-stream flush of
79	    /// a buffered stop reason with no terminal event yet is handled
80	    /// separately by `finish()`.
81	    pub(crate) fn consume(
82	        &mut self,
83	        event: AnthropicEvent,
84	    ) -> Result<Vec<Result<ModelEvent, ModelError>>, ModelError> {
85	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
86	        match event {
87	            AnthropicEvent::MessageStart { message } => {
88	                let MessageStartUsage {
89	                    input_tokens,
90	                    cache_read_input_tokens,
91	                    ..
92	                } = message.usage;
93	                self.last_input_tokens = input_tokens;
94	                self.last_cached_input_tokens = cache_read_input_tokens;
95	                out.push(Ok(ModelEvent::Usage {
96	                    input_tokens,
97	                    output_tokens: 0,
98	                    cached_input_tokens: cache_read_input_tokens,
99	                    reasoning_tokens: None,
100	                }));
101	            }
102	            AnthropicEvent::ContentBlockStart {
103	                index,
104	                content_block,
105	            } => match content_block {
106	                ContentBlockHead::Text => {
107	                    self.blocks.insert(index, BlockState::Text);
108	                }
109	                ContentBlockHead::Thinking {
110	                    thinking,
111	                    signature,
112	                } => {
113	                    self.blocks.insert(
114	                        index,
115	                        BlockState::Thinking {
116	                            text: thinking,
117	                            signature,
118	                        },
119	                    );
120	                }
121	                ContentBlockHead::RedactedThinking { data } => {
122	                    self.blocks
123	                        .insert(index, BlockState::RedactedThinking { data });
124	                }
125	                ContentBlockHead::ToolUse { id, name, .. } => {
126	                    if self.synthesizing_output && name == SYNTHESIZED_TOOL_NAME {
127	                        self.synthesized_tool_index = Some(index);
128	                    } else {
129	                        self.other_tool_fired = true;
130	                    }
131	                    self.blocks.insert(
132	                        index,
133	                        BlockState::ToolUse {
134	                            call_id: id,
135	                            name,
136	                            name_emitted: false,
137	                        },
138	                    );
139	                }
140	            },
141	            AnthropicEvent::ContentBlockDelta { index, delta } => match delta {
142	                ContentBlockDelta::TextDelta { text } => {
143	                    out.push(Ok(ModelEvent::TokenDelta { text }));
144	                }
145	                ContentBlockDelta::ThinkingDelta { thinking } => {
146	                    if let Some(BlockState::Thinking { text, .. }) = self.blocks.get_mut(&index) {
147	                        text.push_str(&thinking);
148	                    }
149	                    out.push(Ok(ModelEvent::ReasoningDelta { text: thinking }));
150	                }
151	                ContentBlockDelta::SignatureDelta { signature } => {
152	                    if let Some(BlockState::Thinking {
153	                        signature: joined, ..
154	                    }) = self.blocks.get_mut(&index)
155	                    {
156	                        joined.push_str(&signature);
157	                    } else {
158	                        tracing::debug!(
159	                            target: "paigasus::anthropic::stream",
160	                            index,
161	                            "signature_delta for a block that is not open; dropped",
162	                        );
163	                    }
164	                }
165	                ContentBlockDelta::InputJsonDelta { partial_json } => {
166	                    let is_synth = Some(index) == self.synthesized_tool_index;
167	                    if is_synth {
168	                        out.push(Ok(ModelEvent::TokenDelta { text: partial_json }));
169	                    } else if let Some(BlockState::ToolUse {
170	                        call_id,
171	                        name,
172	                        name_emitted,
173	                    }) = self.blocks.get_mut(&index)
174	                    {
175	                        let (emit_name, call_id_out) = if *name_emitted {
176	                            (None, call_id.clone())
177	                        } else {
178	                            *name_emitted = true;
179	                            (Some(name.clone()), call_id.clone())
180	                        };
181	                        out.push(Ok(ModelEvent::ToolCallDelta {
182	                            call_id: call_id_out,
183	                            name: emit_name,
184	                            args_delta: partial_json,
185	                        }));
186	                    } else {
187	                        // Protocol violation: input_json_delta only ever
188	                        // applies to a tool_use content block. Surface it
189	                        // rather than silently dropping (which would mask
190	                        // a malformed upstream stream).
191	                        return Err(ModelError::Transport(format!(
192	                            "anthropic stream: input_json_delta at index {index} \
193	                             has no preceding tool_use content_block_start"
194	                        )));
195	                    }
196	                }
197	            },
198	            AnthropicEvent::ContentBlockStop { index } => {
199	                self.stop_block(index, &mut out);
200	            }
201	            AnthropicEvent::MessageDelta { delta, usage } => {
202	                // A `message_delta` after the terminal event is a protocol
203	                // violation (e.g. a second `message_delta` re-arming
204	                // `stop_reason` post-`message_stop`, see
205	                // `second_message_delta_after_message_stop_does_not_double_finish`).
206	                // Emitting its `Usage` would put an event after `Finish`,
207	                // which the core contract forbids.
208	                if !self.terminal_emitted {
209	                    if let Some(MessageDeltaUsage { output_tokens }) = usage {
210	                        out.push(Ok(ModelEvent::Usage {
211	                            input_tokens: self.last_input_tokens,
212	                            output_tokens,
213	                            cached_input_tokens: self.last_cached_input_tokens,
214	                            reasoning_tokens: None,
215	                        }));
216	                    }
217	                }
218	                if let Some(reason) = delta.stop_reason {
219	                    self.stop_reason = Some(reason);
220	                }
221	            }
222	            AnthropicEvent::MessageStop => {
223	                if let Some(reason) = self.stop_reason.take() {
224	                    if !self.terminal_emitted {
225	                        self.terminal_emitted = true;
226	                        out.push(self.finish_or_error(&reason));
227	                    }
228	                }
229	            }
230	            AnthropicEvent::Ping => {}
231	            AnthropicEvent::Error { error } => {
232	                return Err(map_error_type(None, &error.ty, &error.message, None));
233	            }
234	        }
235	        Ok(out)
236	    }
237	
238	    /// Close the block at `index`: keep a valid thinking block and record the
239	    /// positions of the text and `tool_use` blocks.
240	    fn stop_block(&mut self, index: u32, out: &mut Vec<Result<ModelEvent, ModelError>>) {
241	        // No event can follow `Finish`, so a block stop after the terminal
242	        // event gives no provider data.
243	        if self.terminal_emitted {
244	            tracing::debug!(
245	                target: "paigasus::anthropic::stream",
246	                index,
247	                "content_block_stop after the terminal event",
248	            );
249	            return;
250	        }
251	        let Some(state) = self.blocks.remove(&index) else {
252	            tracing::debug!(
253	                target: "paigasus::anthropic::stream",
254	                index,
255	                "content_block_stop for a block that is not open",
256	            );
257	            return;
258	        };
259	        match state {
260	            BlockState::Thinking { text, signature } => self.keep_block(
261	                index,
262	                "thinking",
263	                ThinkingBlock::Thinking {
264	                    thinking: text,
265	                    signature,
266	                },
267	                out,
268	            ),
269	            BlockState::RedactedThinking { data } => self.keep_block(
270	                index,
271	                "redacted_thinking",
272	                ThinkingBlock::RedactedThinking { data },
273	                out,
274	            ),
275	            BlockState::Text => {
276	                if !self.text_position_recorded {
277	                    self.text_position_recorded = true;
278	                    self.position(AnthropicData::Text { index }.into_event(None), out);
279	                }
280	            }
281	            BlockState::ToolUse {
282	                call_id,
283	                name_emitted,
284	                ..
285	            } => {
286	                if name_emitted && Some(index) != self.synthesized_tool_index {
287	                    self.position(
288	                        AnthropicData::ToolUse { index }.into_event(Some(call_id)),
289	                        out,
290	                    );
291	                }
292	            }
293	        }
294	    }
295	
296	    /// Emit a valid thinking block, then every position that waits for it.
297	    fn keep_block(
298	        &mut self,
299	        index: u32,
300	        kind: &str,
301	        block: ThinkingBlock,
302	        out: &mut Vec<Result<ModelEvent, ModelError>>,
303	    ) {
304	        if !block.is_valid() {
305	            tracing::debug!(
306	                target: "paigasus::anthropic::stream",
307	                index,
308	                kind,
309	                "thinking block without signature or data is not kept",
310	            );
311	            return;
312	        }
313	        out.push(Ok(AnthropicData::Block { index, block }.into_event(None)));
314	        if !self.block_emitted {
315	            self.block_emitted = true;
316	            out.extend(self.waiting_positions.drain(..).map(Ok));
317	        }
318	    }
319	
320	    /// Emit a position record now, or hold it until the first `block` part.
321	    fn position(&mut self, event: ModelEvent, out: &mut Vec<Result<ModelEvent, ModelError>>) {
322	        if self.block_emitted {
323	            out.push(Ok(event));
324	        } else {
325	            self.waiting_positions.push(event);
326	        }
327	    }
328	
329	    /// Flush a stop reason buffered from `message_delta` when the response
330	    /// body ends cleanly before `message_stop` arrived.
331	    ///
332	    /// Returns `None` when a terminal event was already emitted — the
333	    /// well-formed path, where `message_stop` drained the buffer — or when no
334	    /// stop reason was ever observed. A stream that ended *before*
335	    /// `message_delta` is never reported as a clean `Stop`; one that ended
336	    /// *after* it is, because `message_delta`'s `stop_reason` is the model's
337	    /// own authoritative decision and `message_stop` is only a frame
338	    /// terminator.
339	    ///
340	    /// `terminal_emitted` — not `stop_reason` being `Some` — is the guard.
341	    /// A second `message_delta` can re-arm the buffer after `message_stop`
342	    /// already emitted, and that must not produce a second terminal event.
343	    ///
344	    /// **Clean-EOF path only.** Never call this on the cancellation or
345	    /// transport-error paths — see `model.rs`.
346	    pub(crate) fn finish(&mut self) -> Option<Result<ModelEvent, ModelError>> {
347	        if self.terminal_emitted {
348	            return None;
349	        }
350	        let reason = self.stop_reason.take()?;
351	        self.terminal_emitted = true;
352	        tracing::warn!(
353	            target: "paigasus::anthropic::stream",
354	            stop_reason = %reason,
355	            "stream body ended without message_stop; flushing buffered stop reason",
356	        );
357	        Some(self.finish_or_error(&reason))
358	    }
359	
360	    fn finish_or_error(&self, reason: &str) -> Result<ModelEvent, ModelError> {
361	        match reason {
362	            "end_turn" | "stop_sequence" => Ok(ModelEvent::Finish {
363	                reason: FinishReason::Stop,
364	            }),
365	            "max_tokens" => Ok(ModelEvent::Finish {
366	                reason: FinishReason::Length,
367	            }),
368	            "tool_use" => {
369	                if self.synthesizing_output && !self.other_tool_fired {
370	                    Ok(ModelEvent::Finish {
371	                        reason: FinishReason::Stop,
372	                    })
373	                } else if self.synthesizing_output && self.other_tool_fired {
374	                    Err(ModelError::Other(anyhow::anyhow!(
375	                        "structured output: model fired both a real tool and the synthesized output tool"
376	                    )))
377	                } else {
378	                    Ok(ModelEvent::Finish {
379	                        reason: FinishReason::ToolCalls,
380	                    })
381	                }
382	            }
383	            "refusal" => Err(ModelError::Refused {
384	                reason: "model refused".to_owned(),
385	            }),
386	            other => Ok(ModelEvent::Finish {
387	                reason: FinishReason::Other(other.to_owned()),
388	            }),
389	        }
390	    }
391	}
