12	/// One thinking block of a response, as Anthropic sent it.
13	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
14	#[serde(tag = "type", rename_all = "snake_case")]
15	pub(crate) enum ThinkingBlock {
16	    /// A `thinking` block with its text and its signature.
17	    Thinking {
18	        /// The joined thinking text. It can be empty.
19	        thinking: String,
20	        /// The signature that Anthropic checks on a later request.
21	        signature: String,
22	    },
23	    /// A `redacted_thinking` block with its opaque data.
24	    RedactedThinking {
25	        /// The opaque data that Anthropic checks on a later request.
26	        data: String,
27	    },
28	}
29	
30	impl ThinkingBlock {
31	    /// A block is valid when Anthropic can check it on a later request.
