98	    /// Make the `ModelEvent` that carries this data.
99	    pub(crate) fn into_event(self, call_id: Option<String>) -> ModelEvent {
100	        ModelEvent::ProviderData {
101	            provider: PROVIDER_DATA_KEY.to_owned(),
102	            call_id,
103	            data: serde_json::to_value(self).expect("AnthropicData serializes"),
