108	/// Read the data of one part of this crate.
109	///
110	/// Returns `None` with no log for a part that is not `ProviderData` or that
111	/// has the key of another provider. Returns `None` with a debug log for a part
112	/// with this key that does not parse, or that holds a block that is not valid.
113	/// The log never holds the content of the part.
114	pub(crate) fn from_part(part: &ContentPart) -> Option<(AnthropicData, Option<&str>)> {
115	    let ContentPart::ProviderData {
116	        provider,
117	        call_id,
118	        data,
119	    } = part
120	    else {
121	        return None;
122	    };
123	    if provider != PROVIDER_DATA_KEY {
124	        return None;
125	    }
126	    // The parse error is not logged, because it can hold a value of the data.
127	    let Ok(parsed) = AnthropicData::deserialize(data) else {
128	        tracing::debug!(
129	            target: "paigasus::anthropic::translate",
130	            "skipping anthropic provider data that does not parse",
131	        );
132	        return None;
133	    };
134	    if let AnthropicData::Block { index, block } = &parsed {
135	        if !block.is_valid() {
136	            tracing::debug!(
137	                target: "paigasus::anthropic::translate",
138	                index = *index,
139	                block_type = block.type_name(),
140	                "skipping anthropic thinking block that is not valid",
141	            );
142	            return None;
143	        }
144	    }
145	    Some((parsed, call_id.as_deref()))
146	}
