162	
163	    #[test]
164	    fn data_serializes_to_the_documented_shapes() {
165	        let thinking = AnthropicData::Block {
166	            index: 0,
167	            block: ThinkingBlock::Thinking {
168	                thinking: "t".to_owned(),
169	                signature: "SIG_FAKE_1".to_owned(),
170	            },
171	        };
172	        assert_eq!(
173	            serde_json::to_value(&thinking).unwrap(),
174	            json!({"kind":"block","index":0,"block":{"type":"thinking","thinking":"t","signature":"SIG_FAKE_1"}})
175	        );
176	        let redacted = AnthropicData::Block {
177	            index: 1,
178	            block: ThinkingBlock::RedactedThinking {
179	                data: "REDACTED_FAKE_1".to_owned(),
180	            },
181	        };
182	        assert_eq!(
183	            serde_json::to_value(&redacted).unwrap(),
184	            json!({"kind":"block","index":1,"block":{"type":"redacted_thinking","data":"REDACTED_FAKE_1"}})
185	        );
186	        assert_eq!(
187	            serde_json::to_value(AnthropicData::Text { index: 2 }).unwrap(),
188	            json!({"kind":"text","index":2})
189	        );
190	        assert_eq!(
191	            serde_json::to_value(AnthropicData::ToolUse { index: 3 }).unwrap(),
192	            json!({"kind":"tool_use","index":3})
193	        );
194	    }
