201	                provider,
202	                call_id,
203	                data,
204	            } => {
205	                assert_eq!(provider, PROVIDER_DATA_KEY);
206	                assert_eq!(call_id.as_deref(), Some("tu_1"));
207	                assert_eq!(data, json!({"kind":"tool_use","index":3}));
208	            }
209	            other => panic!("expected ProviderData, got {other:?}"),
210	        }
211	    }
