1	//! `Vec<Item>` + `ModelRequest` → Anthropic Messages request body.
2	//!
3	//! Rules per the SMA-317 spec § "Wire translation". The translator
4	//! produces a `serde_json::Value` rather than typed structs to keep the
5	//! wire-snapshot tests readable.
6	//!
7	//! SMA-840: an assistant message can hold `ProviderData` parts of this crate.
8	//! They carry the `thinking` and `redacted_thinking` blocks of the response,
9	//! and the positions of its first `text` block and its `tool_use` blocks. The
10	//! translator sends the blocks back and puts the blocks of each source
11	//! message in their response order. A history with no such part builds as
12	//! before.
13	
14	use std::collections::{HashMap, VecDeque};
15	
16	use paigasus_helikon_core::{ContentPart, Item};
17	use serde_json::{json, Value};
18	
19	use crate::provider_data::{self, AnthropicData};
20	
21	/// Output of [`translate_messages`]: the top-level `system` field (string
22	/// or block-array form) and the `messages` array.
23	pub(crate) struct TranslatedMessages {
24	    pub(crate) system: Option<Value>,
25	    pub(crate) messages: Value,
26	    /// `true` when the last user message produced no message, no kept
27	    /// message or tool item follows it (dropped assistant items do not
28	    /// count), and the last sent message is an assistant one.
29	    pub(crate) trailing_message_dropped: bool,
30	}
31	
32	/// The sort key of a block inside its group.
33	#[derive(Debug, Clone, Copy)]
34	enum SortKey {
35	    /// `(index, 1)`, where `index` is the content-block index of the
36	    /// response. A `tool_use` block with no position has `(u64::MAX, 1)`.
37	    At(u64, u8),
38	    /// A text block of a group with no `text` position. The key becomes
39	    /// `(k, 0)`, where `k` is the smallest keyed `tool_use` index of the group
40	    /// in the same wire message, or `u64::MAX` when there is none.
41	    BeforeFirstToolUse,
42	}
43	
44	impl SortKey {
45	    fn resolve(self, first_tool_use: u64) -> (u64, u8) {
46	        match self {
47	            Self::At(index, rank) => (index, rank),
48	            Self::BeforeFirstToolUse => (first_tool_use, 0),
49	        }
50	    }
51	}
52	
53	/// The place of a block in the response order of its source message.
54	#[derive(Debug, Clone, Copy)]
55	struct Slot {
56	    /// The source message of the block. Keys of different groups are never
57	    /// compared.
58	    group: usize,
59	    key: SortKey,
60	    /// `true` when the source message has `tool_use` positions. Then its
61	    /// thinking blocks need a `tool_use` block of the group beside them that
62	    /// took one of these positions.
63	    needs_tool_use: bool,
64	}
65	
66	impl Slot {
67	    /// `true` when `block` lets the thinking blocks of this group stay: a
68	    /// `text` or `tool_use` block of the same group. When the group needs a
69	    /// `tool_use` block, only a `tool_use` block that took a position of the
70	    /// group counts. A call with no position did not come with the thinking
71	    /// block, so it does not count.
72	    fn is_kept_by(&self, block: &WireBlock) -> bool {
73	        let Some(slot) = block.slot.filter(|s| s.group == self.group) else {
74	            return false;
75	        };
76	        let took_position = matches!(slot.key, SortKey::At(index, _) if index != u64::MAX);
77	        !block.is_thinking() && (!self.needs_tool_use || (block.is_tool_use() && took_position))
78	    }
79	}
80	
81	/// One content block of a wire message. Only `value` reaches the JSON.
82	#[derive(Debug, Clone, Default)]
83	struct WireBlock {
84	    value: Value,
85	    /// `None` for a block that does not move in the final sort.
86	    slot: Option<Slot>,
87	}
88	
89	impl WireBlock {
90	    fn plain(value: Value) -> Self {
91	        Self { value, slot: None }
92	    }
93	
94	    fn kind(&self) -> &str {
95	        self.value["type"].as_str().unwrap_or("")
96	    }
97	
98	    fn is_tool_use(&self) -> bool {
99	        self.kind() == "tool_use"
100	    }
101	
102	    fn is_thinking(&self) -> bool {
103	        matches!(self.kind(), "thinking" | "redacted_thinking")
104	    }
105	}
106	
107	/// One message of the `messages` array, before it becomes JSON.
108	#[derive(Debug, Clone)]
109	struct WireMessage {
110	    role: &'static str,
111	    content: Vec<WireBlock>,
112	}
113	
114	impl WireMessage {
115	    /// `true` when the message holds a block that lets the thinking blocks
116	    /// of the group of `slot` stay (see [`Slot::is_kept_by`]).
117	    fn keeps_thinking_of(&self, slot: Slot) -> bool {
118	        self.content.iter().any(|b| slot.is_kept_by(b))
119	    }
120	
121	    fn into_value(mut self) -> Value {
122	        drop_thinking_without_own_block(&mut self.content);
123	        sort_groups(&mut self.content);
124	        let content: Vec<Value> = self.content.into_iter().map(|b| b.value).collect();
125	        json!({"role": self.role, "content": content})
126	    }
127	}
128	
129	/// The Anthropic positions of one source message: an `AssistantMessage`
130	/// with at least one valid part of this crate, together with the
131	/// `Item::ToolCall` items that follow it before the next `AssistantMessage`
132	/// or the next user message with a part that is not a tool result.
133	#[derive(Debug, Clone)]
134	struct Source {
135	    group: usize,
136	    /// The wire message that holds the blocks of the `AssistantMessage`.
137	    /// `None` when it gave no block.
138	    wire: Option<usize>,
139	    /// The `tool_use` positions by call id, in the order of the parts.
140	    tool_positions: HashMap<String, VecDeque<u64>>,
141	    /// `true` when the message has at least one `tool_use` position.
142	    needs_tool_use: bool,
143	}
144	
145	impl Source {
146	    /// The key of the next `tool_use` block with `call_id`. Each position is
147	    /// used once, so a repeated id takes its positions in order.
148	    fn slot(&self, key: SortKey) -> Slot {
149	        Slot {
150	            group: self.group,
151	            key,
152	            needs_tool_use: self.needs_tool_use,
153	        }
154	    }
155	
156	    fn tool_key(&mut self, call_id: &str) -> SortKey {
157	        let index = self
158	            .tool_positions
159	            .get_mut(call_id)
160	            .and_then(VecDeque::pop_front);
161	        SortKey::At(index.unwrap_or(u64::MAX), 1)
162	    }
163	}
164	
165	/// The translator state before the item that made a tentative message.
166	#[derive(Debug)]
167	struct Saved {
168	    item: usize,
169	    messages_len: usize,
170	    system_len: usize,
171	    pending_tool_use: Vec<WireBlock>,
172	    pending_tool_results: Vec<Value>,
173	    last_item_dropped: bool,
174	    next_group: usize,
175	    source: Option<Source>,
176	}
177	
178	/// A wire assistant message that an item with only thinking blocks made.
179	///
180	/// It stays the last message until a message is pushed after it. If the
181	/// keep rule then fails for it (see [`Slot::is_kept_by`]), the translator
182	/// goes back to `saved`, drops the thinking blocks of the item, and
183	/// translates again from that item. At the end, the translator always goes
184	/// back, because the last assistant message sends no thinking block. The
185	/// item then counts as empty, as it did before SMA-840: no flush, no
186	/// message, and no change to the flag.
187	#[derive(Debug)]
188	struct Tentative {
189	    msg: usize,
190	    /// The slot of the thinking blocks of the item.
191	    slot: Slot,
192	    saved: Saved,
193	}
194	
195	/// The signal to go back to the saved state of the tentative message.
196	struct Rollback;
197	
198	#[derive(Debug, Default)]
199	struct Translator {
200	    system_text: String,
201	    messages: Vec<WireMessage>,
202	    pending_tool_use: Vec<WireBlock>,
203	    pending_tool_results: Vec<Value>,
204	    last_item_dropped: bool,
205	    next_group: usize,
206	    source: Option<Source>,
207	    tentative: Option<Tentative>,
208	    /// Tentative messages that a later push kept, in push order. A restore
209	    /// can make one of them the last message again. Then it is tentative
210	    /// again, because the end of the history can still drop its thinking.
211	    kept: Vec<Tentative>,
212	}
213	
214	/// Translate the conversation into Anthropic's request shape.
215	///
216	/// `system` is `None` when no `Item::System` has non-blank text. `messages`
217	/// is always an array. Text parts that are empty or whitespace only, and
218	/// messages left with no blocks, are dropped because the API rejects them.
219	///
220	/// A source message keeps its thinking blocks only when their wire message
221	/// also holds a `text` or `tool_use` block of the same source message. When
222	/// the source message has `tool_use` positions, that block must be one of
223	/// its own `tool_use` blocks. (A hand-off transcript or a trimmed history can
224	/// lose the calls of a response.) The last wire message, when it is an
225	/// assistant message, sends no thinking block. When a rule fails, the
226	/// thinking blocks are dropped, and the item builds as if it had no
227	/// Anthropic part. A thinking block must not go into a round that a
228	/// different response made.
229	///
230	/// - The thinking blocks of an item that joins an open round are removed in
231	///   the final pass when the rule fails. These blocks change no other
232	///   decision, so the result is the same as with no such blocks.
233	/// - An item with only thinking blocks that makes a new message can change
234	///   the flushes. When the rule fails for it, the translator goes back and
235	///   translates again from that item, with its thinking blocks dropped.
236	///   Decisions go in item order.
237	pub(crate) fn translate_messages(items: &[Item]) -> TranslatedMessages {
238	    let mut t = Translator::default();
239	    let mut drop_thinking = vec![false; items.len()];
240	    let mut i = 0;
241	    loop {
242	        let done = i == items.len();
243	        let step = if done {
244	            t.finish()
245	        } else {
246	            t.step(i, &items[i], drop_thinking[i])
247	        };
248	        match step {
249	            Ok(()) if done => break,
250	            Ok(()) => i += 1,
251	            Err(Rollback) => {
252	                let tentative = t
253	                    .tentative
254	                    .take()
255	                    .expect("a rollback needs a tentative message");
256	                i = tentative.saved.item;
257	                // Each rollback drops one more item, so the loop ends.
258	                drop_thinking[i] = true;
259	                t.restore(tentative.saved);
260	            }
261	        }
262	    }
263	    t.into_output()
264	}
265	
266	impl Translator {
267	    fn step(&mut self, i: usize, item: &Item, drop_thinking: bool) -> Result<(), Rollback> {
268	        match item {
269	            Item::System { content } => {
270	                self.flush_pending_assistant()?;
271	                self.flush_pending_user()?;
272	                if !self.system_text.is_empty() {
273	                    self.system_text.push('\n');
274	                }
275	                self.system_text.push_str(&text_of(content));
276	            }
277	            Item::UserMessage { content } => {
278	                // A user message with a part that is not a tool result ends
279	                // the source message (the SMA-827 Gemini rule).
280	                if content
281	                    .iter()
282	                    .any(|p| !matches!(p, ContentPart::ToolResult { .. }))
283	                {
284	                    self.source = None;
285	                }
286	                self.flush_pending_assistant()?;
287	                // Pending tool_results go at the front of this user turn.
288	                let mut blocks: Vec<Value> = std::mem::take(&mut self.pending_tool_results);
289	                blocks.extend(user_blocks(content));
290	                self.last_item_dropped = blocks.is_empty();
291	                if !blocks.is_empty() {
292	                    let blocks = blocks.into_iter().map(WireBlock::plain).collect();
293	                    self.push_message("user", blocks)?;
294	                }
295	            }
296	            Item::AssistantMessage { content, agent: _ } => {
297	                let (mut blocks, source) = assistant_blocks(content, self.next_group);
298	                if drop_thinking {
299	                    blocks.retain(|b| !b.is_thinking());
300	                }
301	                // An assistant item with no blocks acts as if it were absent:
302	                // it flushes nothing (so an open tool round stays whole) and
303	                // leaves the flag as it is (a drop of the user turn before
304	                // it still counts). A kept assistant message ends the drop.
305	                //
306	                // A message of only tool uses and thinking blocks is the
307	                // nested form of `Item::ToolCall`, or the accumulator form of
308	                // a thinking round (SMA-834, SMA-840). Inside an open round it
309	                // joins that round, as a call does. A flush would put a user
310	                // turn that lacks some results right after the open assistant
311	                // turn. On this path the last message is an assistant message
312	                // (`round_is_answered` is `true` for an empty trailing
313	                // assistant run). `pending_tool_use` is empty, because each
314	                // `ToolResult` flushes it. So the append keeps the order.
315	                // Setting `last_item_dropped` here is for symmetry. The flag
316	                // is already `false`, because a `ToolResult` came after any
317	                // dropped user message.
318	                let only_tool_uses =
319	                    !blocks.is_empty() && blocks.iter().all(|b| b.is_tool_use() || b.is_thinking());
320	                let joins = only_tool_uses
321	                    && !self.pending_tool_results.is_empty()
322	                    && !round_is_answered(&self.messages, &self.pending_tool_results);
323	                let thinking_only = !blocks.is_empty() && blocks.iter().all(WireBlock::is_thinking);
324	                let saved = (thinking_only && !joins).then(|| self.save(i));
325	                if source.is_some() {
326	                    self.next_group += 1;
327	                }
328	                self.source = source;
329	                if joins {
330	                    self.last_item_dropped = false;
331	                    let target = self.tool_use_target();
332	                    if let Some(source) = &mut self.source {
333	                        source.wire = Some(target);
334	                    }
335	                    self.push_tool_uses(blocks);
336	                } else if !blocks.is_empty() {
337	                    self.flush_pending_assistant()?;
338	                    self.flush_pending_user()?;
339	                    self.last_item_dropped = false;
340	                    let msg = self.messages.len();
341	                    self.push_message("assistant", blocks)?;
342	                    if let Some(source) = &mut self.source {
343	                        source.wire = Some(msg);
344	                    }
345	                    if let Some(saved) = saved {
346	                        // `push_message` cleared any older tentative message.
347	                        debug_assert!(self.tentative.is_none());
348	                        let slot = self
349	                            .source
350	                            .as_ref()
351	                            .map(|s| s.slot(SortKey::At(0, 1)))
352	                            .expect("a thinking block comes from a valid part");
353	                        self.tentative = Some(Tentative { msg, slot, saved });
354	                    }
355	                }
356	            }
357	            Item::ToolCall {
358	                call_id,
359	                name,
360	                args,
361	            } => {
362	                self.last_item_dropped = false;
363	                // A new tool_use follows any results already seen. Close
364	                // that user turn first only when the last assistant round is
365	                // fully answered; otherwise the call joins that round.
366	                if round_is_answered(&self.messages, &self.pending_tool_results) {
367	                    self.flush_pending_user()?;
368	                }
369	                // The call keeps its key only in the wire message that holds
370	                // the blocks of its source message.
371	                let target = self.tool_use_target();
372	                let slot = self.source.as_mut().and_then(|source| {
373	                    let key = source.tool_key(call_id);
374	                    (source.wire == Some(target)).then(|| source.slot(key))
375	                });
376	                let value = json!({
377	                    "type": "tool_use",
378	                    "id": call_id,
379	                    "name": name,
380	                    "input": args,
381	                });
382	                self.push_tool_uses(vec![WireBlock { value, slot }]);
383	            }
384	            Item::ToolResult { call_id, content } => {
385	                self.last_item_dropped = false;
386	                self.flush_pending_assistant()?;
387	                self.pending_tool_results.push(json!({
388	                    "type": "tool_result",
389	                    "tool_use_id": call_id,
390	                    "content": text_of(content),
391	                }));
392	            }
393	            _ => {
394	                tracing::warn!(
395	                    target: "paigasus::anthropic::translate",
396	                    "unknown Item variant; skipping",
397	                );
398	            }
399	        }
400	        Ok(())
401	    }
402	
403	    fn finish(&mut self) -> Result<(), Rollback> {
404	        self.flush_pending_assistant()?;
405	        self.flush_pending_user()?;
406	        // A tentative message at the end is the last assistant message. It
407	        // sends no thinking block, so the item counts as empty.
408	        match self.tentative {
409	            Some(_) => Err(Rollback),
410	            None => Ok(()),
411	        }
412	    }
413	
414	    /// Push a message. A tentative message before it is then complete: keep
415	    /// it when the keep rule holds for it, else go back.
416	    fn push_message(
417	        &mut self,
418	        role: &'static str,
419	        content: Vec<WireBlock>,
420	    ) -> Result<(), Rollback> {
421	        if let Some(t) = &self.tentative {
422	            debug_assert_eq!(
423	                t.msg + 1,
424	                self.messages.len(),
425	                "a tentative message is last"
426	            );
427	            if !self.messages[t.msg].keeps_thinking_of(t.slot) {
428	                return Err(Rollback);
429	            }
430	            self.kept.extend(self.tentative.take());
431	        }
432	        self.messages.push(WireMessage { role, content });
433	        Ok(())
434	    }
435	
436	    fn flush_pending_assistant(&mut self) -> Result<(), Rollback> {
437	        if self.pending_tool_use.is_empty() {
438	            return Ok(());
439	        }
440	        let content = std::mem::take(&mut self.pending_tool_use);
441	        self.push_message("assistant", content)
442	    }
443	
444	    fn flush_pending_user(&mut self) -> Result<(), Rollback> {
445	        if self.pending_tool_results.is_empty() {
446	            return Ok(());
447	        }
448	        let content = std::mem::take(&mut self.pending_tool_results)
449	            .into_iter()
450	            .map(WireBlock::plain)
451	            .collect();
452	        self.push_message("user", content)
453	    }
454	
455	    /// The index of the wire message that `push_tool_uses` adds to now.
456	    fn tool_use_target(&self) -> usize {
457	        match self.messages.last() {
458	            Some(m) if m.role == "assistant" => self.messages.len() - 1,
459	            // Queued blocks flush into the next message.
460	            _ => self.messages.len(),
461	        }
462	    }
463	
464	    /// Add `tool_use` blocks to the open assistant turn. When the last
465	    /// message is an assistant message, extend it. Otherwise queue them.
466	    fn push_tool_uses(&mut self, blocks: Vec<WireBlock>) {
467	        match self.messages.last_mut() {
468	            Some(last) if last.role == "assistant" => last.content.extend(blocks),
469	            _ => self.pending_tool_use.extend(blocks),
470	        }
471	    }
472	
473	    fn save(&self, item: usize) -> Saved {
474	        Saved {
475	            item,
476	            messages_len: self.messages.len(),
477	            system_len: self.system_text.len(),
478	            pending_tool_use: self.pending_tool_use.clone(),
479	            pending_tool_results: self.pending_tool_results.clone(),
480	            last_item_dropped: self.last_item_dropped,
481	            next_group: self.next_group,
482	            source: self.source.clone(),
483	        }
484	    }
485	
486	    /// Go back to `saved`. The messages before `saved.messages_len` did not
487	    /// change after the save: only the last message gets new blocks, and the
488	    /// tentative message and all later ones are at or after that length.
489	    ///
490	    /// `saved` does not hold a tentative message. A tentative message that
491	    /// was active when `saved` was taken was resolved by a later push in the
492	    /// same step. That push is a flush of the pending blocks or the push of
493	    /// the new tentative message. If the older message was not kept, that
494	    /// push rolled back to the older save, and this `saved` was discarded.
495	    /// If it was kept, it is in `kept`. It is the last message at
496	    /// `saved.messages_len`, so the restore makes it tentative again. Its
497	    /// own save is still correct, because no message before its own saved
498	    /// length changed.
499	    fn restore(&mut self, saved: Saved) {
500	        self.messages.truncate(saved.messages_len);
501	        self.system_text.truncate(saved.system_len);
502	        self.pending_tool_use = saved.pending_tool_use;
503	        self.pending_tool_results = saved.pending_tool_results;
504	        self.last_item_dropped = saved.last_item_dropped;
505	        self.next_group = saved.next_group;
506	        self.source = saved.source;
507	        let len = self.messages.len();
508	        self.kept.retain(|t| t.msg < len);
509	        self.tentative = match self.kept.last() {
510	            Some(t) if t.msg + 1 == len => self.kept.pop(),
511	            _ => None,
512	        };
513	    }
514	
515	    fn into_output(self) -> TranslatedMessages {
516	        let trailing_message_dropped =
517	            self.last_item_dropped && self.messages.last().is_some_and(|m| m.role == "assistant");
518	        let system = if self.system_text.trim().is_empty() {
519	            None
520	        } else {
521	            Some(Value::String(self.system_text))
522	        };
523	        let mut messages = self.messages;
524	        // A caller prefill or a continuation ends with an assistant message.
525	        // That message sends no thinking block, and its blocks keep the
526	        // order of the parts.
527	        if let Some(last) = messages.last_mut().filter(|m| m.role == "assistant") {
528	            last.content.retain(|b| !b.is_thinking());
529	            for block in &mut last.content {
530	                block.slot = None;
531	            }
532	        }
533	        let messages = messages.into_iter().map(WireMessage::into_value).collect();
534	        TranslatedMessages {
535	            system,
536	            messages: Value::Array(messages),
537	            trailing_message_dropped,
538	        }
539	    }
540	}
541	
542	/// Remove each thinking block that the keep rule does not keep in this
543	/// message (see [`Slot::is_kept_by`]).
544	fn drop_thinking_without_own_block(content: &mut Vec<WireBlock>) {
545	    let keep: Vec<bool> = content
546	        .iter()
547	        .map(|b| match b.slot {
548	            Some(slot) if b.is_thinking() => content.iter().any(|o| slot.is_kept_by(o)),
549	            _ => true,
550	        })
551	        .collect();
552	    // A source that loses its thinking also loses its sort slots. Its blocks
553	    // then keep the plain order, as without Anthropic metadata.
554	    let lost: Vec<usize> = content
555	        .iter()
556	        .zip(&keep)
557	        .filter(|(b, kept)| !**kept && b.is_thinking())
558	        .filter_map(|(b, _)| b.slot.map(|s| s.group))
559	        .collect();
560	    let mut keep = keep.into_iter();
561	    content.retain(|_| keep.next().unwrap_or(true));
562	    for block in content.iter_mut() {
563	        if block.slot.is_some_and(|s| lost.contains(&s.group)) {
564	            block.slot = None;
565	        }
566	    }
567	}
568	
569	/// Put the blocks of each group back in response order.
570	///
571	/// For each group, take the positions its blocks have in the message, sort
572	/// those blocks by key (stable), and write them back into the same
573	/// positions. Blocks of other groups and blocks with no slot do not move.
574	fn sort_groups(content: &mut [WireBlock]) {
575	    let mut groups: Vec<usize> = Vec::new();
576	    for slot in content.iter().filter_map(|b| b.slot) {
577	        if !groups.contains(&slot.group) {
578	            groups.push(slot.group);
579	        }
580	    }
581	    for group in groups {
582	        let at: Vec<usize> = content
583	            .iter()
584	            .enumerate()
585	            .filter(|(_, b)| b.slot.is_some_and(|s| s.group == group))
586	            .map(|(i, _)| i)
587	            .collect();
588	        let first_tool_use = at
589	            .iter()
590	            .filter(|&&i| content[i].is_tool_use())
591	            .filter_map(|&i| match content[i].slot.map(|s| s.key) {
592	                Some(SortKey::At(index, _)) if index != u64::MAX => Some(index),
593	                _ => None,
594	            })
595	            .min()
596	            .unwrap_or(u64::MAX);
597	        let mut taken: Vec<WireBlock> = at
598	            .iter()
599	            .map(|&i| std::mem::take(&mut content[i]))
600	            .collect();
601	        taken.sort_by_key(|b| b.slot.map(|s| s.key.resolve(first_tool_use)));
602	        for (i, block) in at.into_iter().zip(taken) {
603	            content[i] = block;
604	        }
605	    }
606	}
607	
608	/// `true` when every `tool_use` id in the trailing run of assistant messages
609	/// has a matching `tool_result` in `results`. The API joins adjacent
610	/// assistant messages into one turn, so the whole run is one round. Also
611	/// `true` when there is nothing to compare (no assistant message last), so
612	/// the results then flush as before.
613	fn round_is_answered(messages: &[WireMessage], results: &[Value]) -> bool {
614	    messages
615	        .iter()
616	        .rev()
617	        .take_while(|m| m.role == "assistant")
618	        .flat_map(|m| &m.content)
619	        .filter(|b| b.is_tool_use())
620	        .all(|b| results.iter().any(|r| r["tool_use_id"] == b.value["id"]))
621	}
622	
623	/// The API rejects empty and whitespace-only text blocks.
624	fn is_blank(text: &str) -> bool {
625	    text.trim().is_empty()
626	}
627	
628	fn text_of(parts: &[ContentPart]) -> String {
629	    let mut s = String::new();
630	    for p in parts {
631	        if let ContentPart::Text { text } = p {
632	            if !s.is_empty() {
633	                s.push('\n');
634	            }
635	            s.push_str(text);
636	        }
637	    }
638	    s
639	}
640	
641	fn user_blocks(content: &[ContentPart]) -> Vec<Value> {
642	    use paigasus_helikon_core::MediaSource;
643	    content
644	        .iter()
645	        .filter_map(|p| match p {
646	            ContentPart::Text { text } if is_blank(text) => None,
647	            ContentPart::Text { text } => Some(json!({"type": "text", "text": text})),
648	            ContentPart::ToolResult { call_id, content } => Some(json!({
649	                "type": "tool_result",
650	                "tool_use_id": call_id,
651	                "content": text_of(content),
652	            })),
653	            ContentPart::Image { source } => match source {
654	                MediaSource::Url { url } => Some(json!({
655	                    "type": "image",
656	                    "source": {"type": "url", "url": url},
657	                })),
658	                MediaSource::Base64 { mime_type, data } => Some(json!({
659	                    "type": "image",
660	                    "source": {
661	                        "type": "base64",
662	                        "media_type": mime_type,
663	                        "data": data,
664	                    },
665	                })),
666	                _ => {
667	                    tracing::warn!(
668	                        target: "paigasus::anthropic::translate",
669	                        "unsupported MediaSource variant; skipping image",
670	                    );
671	                    None
672	                }
673	            },
674	            // Provider data from another provider has no Anthropic form.
675	            ContentPart::ProviderData { .. } => None,
676	            _ => None,
677	        })
678	        .collect()
679	}
680	
681	/// The blocks of one `AssistantMessage`, and its source state.
682	///
683	/// The source state is `Some` only when at least one part of this crate is
684	/// valid. Then each block gets a slot in group `group`. Else no block gets a
685	/// slot, and the message builds as before SMA-840.
686	fn assistant_blocks(content: &[ContentPart], group: usize) -> (Vec<WireBlock>, Option<Source>) {
687	    // Read each part once, so that a skipped part logs once.
688	    let data: Vec<Option<(AnthropicData, Option<&str>)>> =
689	        content.iter().map(provider_data::from_part).collect();
690	    let mut source = data.iter().any(Option::is_some).then(|| Source {
691	        group,
692	        wire: None,
693	        tool_positions: HashMap::new(),
694	        needs_tool_use: false,
695	    });
696	    let mut text_key = SortKey::BeforeFirstToolUse;
697	    if let Some(source) = &mut source {
698	        let mut text_seen = false;
699	        for (d, call_id) in data.iter().flatten() {
700	            match d {
701	                // The stream writes a position for the first text block only.
702	                AnthropicData::Text { index } if !text_seen => {
703	                    text_seen = true;
704	                    text_key = SortKey::At(u64::from(*index), 1);
705	                }
706	                AnthropicData::ToolUse { index } => match call_id {
707	                    Some(id) => source
708	                        .tool_positions
709	                        .entry((*id).to_owned())
710	                        .or_default()
711	                        .push_back(u64::from(*index)),
712	                    None => tracing::debug!(
713	                        target: "paigasus::anthropic::translate",
714	                        index = *index,
715	                        "skipping anthropic tool_use position with no call id",
716	                    ),
717	                },
718	                _ => {}
719	            }
720	        }
721	        source.needs_tool_use = !source.tool_positions.is_empty();
722	    }
723	    let base = source.as_ref().map(|s| s.slot(SortKey::BeforeFirstToolUse));
724	    let slot = |key| base.map(|base| Slot { key, ..base });
725	    let mut blocks = Vec::new();
726	    for (part, data) in content.iter().zip(&data) {
727	        match part {
728	            ContentPart::Text { text } if is_blank(text) => {}
729	            // Core joins the text of a turn into one part. Each text block
730	            // of the group gets the same key, so the blocks stay in order.
731	            ContentPart::Text { text } => blocks.push(WireBlock {
732	                value: json!({"type": "text", "text": text}),
733	                slot: slot(text_key),
734	            }),
735	            ContentPart::ToolUse {
736	                call_id,
737	                name,
738	                args,
739	            } => {
740	                let slot = source.as_mut().map(|s| {
741	                    let key = s.tool_key(call_id);
742	                    s.slot(key)
743	                });
744	                blocks.push(WireBlock {
745	                    value: json!({
746	                        "type": "tool_use",
747	                        "id": call_id,
748	                        "name": name,
749	                        "input": args,
750	                    }),
751	                    slot,
752	                });
753	            }
754	            // The thinking text travels in the `ProviderData` block part.
755	            ContentPart::Reasoning { .. } => {
756	                tracing::debug!(
757	                    target: "paigasus::anthropic::translate",
758	                    "dropping ContentPart::Reasoning on input; provider data carries the block",
759	                );
760	            }
761	            ContentPart::ProviderData { .. } => {
762	                // Provider data from another provider, and position parts,
763	                // give no block.
764	                if let Some((AnthropicData::Block { index, block }, _)) = data {
765	                    blocks.push(WireBlock {
766	                        value: block.to_wire(),
767	                        slot: slot(SortKey::At(u64::from(*index), 1)),
768	                    });
769	                }
770	            }
771	            _ => {}
772	        }
773	    }
774	    (blocks, source)
775	}
