1	//! `ResponseFormat` → synthesized forced tool + guards.
2	
3	use paigasus_helikon_core::{ResponseFormat, ToolChoice, ToolDef};
4	use serde_json::{json, Value};
5	
6	/// Reserved name for the synthesized output tool. Caller-provided tools
7	/// with this name are rejected by [`validate_tool_names`].
8	pub(crate) const SYNTHESIZED_TOOL_NAME: &str = "__paigasus_structured_output__";
9	
10	/// Outcome of [`synthesize_for_response_format`].
11	pub(crate) struct Synthesized {
12	    /// Extra tool to append to the `tools` array.
13	    pub(crate) tool: Option<Value>,
14	    /// `tool_choice` value to write into the request body.
15	    pub(crate) tool_choice: Option<Value>,
16	    /// True when we synthesized — the stream translator uses this to
17	    /// remap the synthesized tool's `input_json_delta` events to `TokenDelta`.
18	    pub(crate) synthesizing: bool,
19	}
20	
21	/// Reject user tools whose name collides with the reserved synthesized name.
22	///
23	/// Runs **regardless of `ResponseFormat`** — a stray collision pollutes
24	/// the request schema even when synthesis is inactive.
25	pub(crate) fn validate_tool_names(defs: &[ToolDef]) -> Result<(), String> {
26	    for d in defs {
27	        if d.name == SYNTHESIZED_TOOL_NAME {
28	            return Err(format!(
29	                "tool name '{SYNTHESIZED_TOOL_NAME}' is reserved by the Anthropic provider \
30	                 for structured-output synthesis",
31	            ));
32	        }
33	    }
34	    Ok(())
35	}
36	
37	/// Reject (ResponseFormat::JsonSchema|JsonObject) + ToolChoice::Tool combinations.
38	pub(crate) fn validate_conflict(
39	    rf: Option<&ResponseFormat>,
40	    tc: Option<&ToolChoice>,
41	) -> Result<(), String> {
42	    let synthesizing = matches!(
43	        rf,
44	        Some(ResponseFormat::JsonSchema { .. }) | Some(ResponseFormat::JsonObject),
45	    );
46	    let forced_tool = matches!(tc, Some(ToolChoice::Tool { .. }));
47	    if synthesizing && forced_tool {
48	        return Err(
49	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::Tool are \
50	             mutually exclusive on Anthropic"
51	                .to_owned(),
52	        );
53	    }
54	    Ok(())
55	}
56	
57	/// Build the synthesized tool + tool_choice value for the given response format.
58	/// Returns `Synthesized { synthesizing: false, .. }` for `Text` / `None`.
59	pub(crate) fn synthesize_for_response_format(rf: Option<&ResponseFormat>) -> Synthesized {
60	    match rf {
61	        Some(ResponseFormat::JsonSchema { name, schema, .. }) => Synthesized {
62	            tool: Some(json!({
63	                "name": SYNTHESIZED_TOOL_NAME,
64	                "description": format!("Return data matching the {name} schema."),
65	                "input_schema": schema,
66	            })),
67	            tool_choice: Some(json!({"type": "tool", "name": SYNTHESIZED_TOOL_NAME})),
68	            synthesizing: true,
69	        },
70	        Some(ResponseFormat::JsonObject) => Synthesized {
71	            tool: Some(json!({
72	                "name": SYNTHESIZED_TOOL_NAME,
73	                "description": "Return a JSON object.",
74	                "input_schema": {"type": "object"},
75	            })),
76	            tool_choice: Some(json!({"type": "tool", "name": SYNTHESIZED_TOOL_NAME})),
77	            synthesizing: true,
78	        },
79	        _ => Synthesized {
80	            tool: None,
81	            tool_choice: None,
82	            synthesizing: false,
83	        },
84	    }
85	}
