1	//! Anthropic SSE event envelope deserialization.
2	
3	use serde::Deserialize;
4	use serde_json::Value;
5	
6	/// The typed envelope for one SSE event from `/v1/messages` (stream mode).
7	///
8	/// `#[serde(tag = "type")]` matches Anthropic's `"type": "message_start"` etc.
9	#[derive(Debug, Clone, Deserialize)]
10	#[serde(tag = "type")]
11	pub(crate) enum AnthropicEvent {
12	    #[serde(rename = "message_start")]
13	    MessageStart { message: MessageStartPayload },
14	    #[serde(rename = "content_block_start")]
15	    ContentBlockStart {
16	        index: u32,
17	        content_block: ContentBlockHead,
18	    },
19	    #[serde(rename = "content_block_delta")]
20	    ContentBlockDelta {
21	        index: u32,
22	        delta: ContentBlockDelta,
23	    },
24	    #[serde(rename = "content_block_stop")]
25	    ContentBlockStop { index: u32 },
26	    #[serde(rename = "message_delta")]
27	    MessageDelta {
28	        delta: MessageDeltaPayload,
29	        usage: Option<MessageDeltaUsage>,
30	    },
31	    #[serde(rename = "message_stop")]
32	    MessageStop,
33	    #[serde(rename = "ping")]
34	    Ping,
35	    #[serde(rename = "error")]
36	    Error { error: AnthropicErrorPayload },
37	}
38	
39	#[derive(Debug, Clone, Deserialize)]
40	pub(crate) struct MessageStartPayload {
41	    pub(crate) usage: MessageStartUsage,
42	}
43	
44	#[derive(Debug, Clone, Deserialize)]
45	pub(crate) struct MessageStartUsage {
46	    pub(crate) input_tokens: u32,
47	    #[serde(default)]
48	    pub(crate) cache_read_input_tokens: Option<u32>,
49	    #[serde(default)]
50	    #[allow(dead_code)]
51	    pub(crate) cache_creation_input_tokens: Option<u32>,
52	}
53	
54	#[derive(Debug, Clone, Deserialize)]
55	#[serde(tag = "type")]
56	pub(crate) enum ContentBlockHead {
57	    #[serde(rename = "text")]
58	    Text,
59	    #[serde(rename = "thinking")]
60	    Thinking {
61	        #[serde(default)]
62	        thinking: String,
63	        #[serde(default)]
64	        signature: String,
65	    },
66	    #[serde(rename = "redacted_thinking")]
67	    RedactedThinking { data: String },
68	    #[serde(rename = "tool_use")]
69	    ToolUse {
70	        id: String,
71	        name: String,
72	        #[serde(default)]
73	        #[allow(dead_code)]
74	        input: Value,
75	    },
76	}
77	
78	#[allow(clippy::enum_variant_names)] // Anthropic wire names all end in `_delta`; renaming would break serde
79	#[derive(Debug, Clone, Deserialize)]
80	#[serde(tag = "type")]
81	pub(crate) enum ContentBlockDelta {
82	    #[serde(rename = "text_delta")]
83	    TextDelta { text: String },
84	    #[serde(rename = "thinking_delta")]
85	    ThinkingDelta { thinking: String },
86	    #[serde(rename = "signature_delta")]
87	    SignatureDelta { signature: String },
88	    #[serde(rename = "input_json_delta")]
89	    InputJsonDelta { partial_json: String },
90	}
91	
92	#[derive(Debug, Clone, Deserialize)]
93	pub(crate) struct MessageDeltaPayload {
94	    #[serde(default)]
95	    pub(crate) stop_reason: Option<String>,
96	}
97	
98	#[derive(Debug, Clone, Deserialize)]
99	pub(crate) struct MessageDeltaUsage {
100	    pub(crate) output_tokens: u32,
101	}
102	
103	#[derive(Debug, Clone, Deserialize)]
104	pub(crate) struct AnthropicErrorPayload {
105	    #[serde(rename = "type")]
106	    pub(crate) ty: String,
107	    pub(crate) message: String,
108	}
109	
110	#[cfg(test)]
111	mod tests {
112	    use super::*;
113	    use serde_json::json;
114	
115	    #[test]
116	    fn deserializes_message_start_with_cache_tokens() {
117	        let v = json!({
118	            "type": "message_start",
119	            "message": {
120	                "usage": {
121	                    "input_tokens": 100,
122	                    "cache_read_input_tokens": 80,
123	                    "cache_creation_input_tokens": 0
124	                }
125	            }
126	        });
127	        let e: AnthropicEvent = serde_json::from_value(v).unwrap();
128	        match e {
129	            AnthropicEvent::MessageStart { message } => {
130	                assert_eq!(message.usage.input_tokens, 100);
131	                assert_eq!(message.usage.cache_read_input_tokens, Some(80));
132	            }
133	            other => panic!("wrong variant {other:?}"),
134	        }
135	    }
136	
137	    #[test]
138	    fn deserializes_text_delta() {
139	        let v = json!({
140	            "type": "content_block_delta",
141	            "index": 0,
142	            "delta": {"type": "text_delta", "text": "Hi"}
