38	const REDACT_TRIGGER: &str = "ANTHROPIC_MAGIC_STRING_TRIGGER_REDACTED_THINKING_46C9A13E193C177646C7398A98432ECCCE4C1253D5E2D82641AC0E52CC2876CB";
39	
40	const INTERLEAVED_BETA: &str = "interleaved-thinking-2025-05-14";
