131	/// Invoke the model and collect one turn. A stream error fails the test.
132	async fn run_turn(model: &dyn Model, request: ModelRequest, label: &str) -> ModelTurn {
133	    let mut stream = model
134	        .invoke(request, CancellationToken::new())
135	        .await
136	        .unwrap_or_else(|e| panic!("{label}: invoke failed: {e}"));
137	    let mut acc = ModelTurnAccumulator::new("root");
138	    while let Some(event) = stream.next().await {
139	        acc.observe(&event.unwrap_or_else(|e| panic!("{label}: stream error: {e}")));
140	    }
141	    acc.finish()
142	        .unwrap_or_else(|e| panic!("{label}: the turn does not assemble: {e}"))
143	}
