145	/// The thinking blocks of the parts of the items, in order.
146	fn blocks_of_parts<'a>(parts: impl Iterator<Item = &'a ContentPart>) -> Vec<ThinkingBlock> {
147	    parts
148	        .filter_map(|part| match from_part(part) {
149	            Some((AnthropicData::Block { block, .. }, _)) => Some(block),
150	            _ => None,
151	        })
152	        .collect()
153	}
154	
155	fn blocks_of_items(items: &[Item]) -> Vec<ThinkingBlock> {
156	    blocks_of_parts(items.iter().flat_map(|item| match item {
157	        Item::AssistantMessage { content, .. } => content.as_slice(),
158	        _ => &[],
159	    }))
160	}
