162	fn signatures(blocks: &[ThinkingBlock]) -> Vec<String> {
163	    blocks
164	        .iter()
165	        .filter_map(|b| match b {
166	            ThinkingBlock::Thinking { signature, .. } => Some(signature.clone()),
167	            ThinkingBlock::RedactedThinking { .. } => None,
168	        })
169	        .collect()
170	}
171	
172	fn redacted_data(blocks: &[ThinkingBlock]) -> Vec<String> {
173	    blocks
174	        .iter()
175	        .filter_map(|b| match b {
176	            ThinkingBlock::RedactedThinking { data } => Some(data.clone()),
177	            ThinkingBlock::Thinking { .. } => None,
178	        })
179	        .collect()
180	}
