182	fn tool_calls(items: &[Item]) -> Vec<(String, String)> {
183	    items
184	        .iter()
185	        .filter_map(|item| match item {
186	            Item::ToolCall { call_id, name, .. } => Some((call_id.clone(), name.clone())),
187	            _ => None,
188	        })
189	        .collect()
190	}
