192	/// The turn 2 request: the messages of turn 1, then one result per call.
193	fn second_request(first: &ModelRequest, items: &[Item]) -> ModelRequest {
194	    let mut request = first.clone();
195	    request.messages.extend(items.iter().cloned());
196	    for (call_id, name) in tool_calls(items) {
197	        request.messages.push(Item::ToolResult {
198	            call_id,
199	            content: vec![ContentPart::Text {
200	                text: tool_result_text(&name).into(),
201	            }],
202	        });
203	    }
204	    request
205	}
