218	/// Turn 1, the check of the turn 2 body, and turn 2. Returns the turn 2 items.
219	async fn thinking_round_trip(model: &AnthropicModel) -> Vec<Item> {
220	    let first = first_request(BASE_PROMPT);
221	    let turn1 = run_turn(model, first.clone(), "turn 1").await;
222	    assert!(
223	        !tool_calls(&turn1.items).is_empty(),
