241	            body.contains(sig.as_str()),
242	            "the turn 2 body does not hold a signature of turn 1 (length {})",
243	            sig.len()
244	        );
245	    }
246	
247	    let turn2 = run_turn(model, second, "turn 2").await;
248	    assert_turn_ok(&turn2, "turn 2");
